// Reviewer probe (throwaway stack only): editor path for a plan draft with no coverages.
const { chromium } = require('/Users/cristiansabogal/Proyectos/multicountry-car-insurance/frontend/node_modules/playwright');
const BASE = 'http://localhost:1337';
const UID = 'api::plan.plan';

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1400, height: 1000 } });
  let auth = null;
  const writes = [];
  page.on('request', (r) => {
    const h = r.headers()['authorization'];
    if (h && r.url().includes('/content-manager/')) auth = h;
    if (r.url().includes(`/content-manager/collection-types/${UID}`) && ['POST', 'PUT'].includes(r.method())) {
      let body = null;
      try { body = JSON.parse(r.postData() || 'null'); } catch { body = '(unparsed)'; }
      writes.push({ method: r.method(), path: new URL(r.url()).pathname.replace(/[a-z0-9]{24}/g, '<id>'), coverages: body && typeof body === 'object' ? JSON.stringify(body.coverages) : String(body) });
    }
  });
  page.on('response', async (r) => {
    if (r.url().includes(`/content-manager/collection-types/${UID}`) && ['POST', 'PUT'].includes(r.request().method())) {
      let msg = '';
      try { const j = await r.json(); msg = j.error ? `${j.error.name}: ${j.error.message} ${JSON.stringify(j.error.details?.errors?.map((e) => e.path.join('.') + ' ' + e.message) ?? [])}` : 'ok'; } catch { msg = '(no json)'; }
      console.log('RESPONSE', r.request().method(), new URL(r.url()).pathname.replace(/[a-z0-9]{24}/g, '<id>'), r.status(), msg);
    }
  });

  await page.goto(`${BASE}/admin/auth/login`);
  await page.getByLabel(/email/i).fill(process.env.STRAPI_ADMIN_EMAIL);
  await page.getByLabel(/^password/i).fill(process.env.STRAPI_ADMIN_PASSWORD);
  await page.getByRole('button', { name: /login/i }).click();
  await page.waitForURL(/\/admin(?!\/auth)/);

  await page.goto(`${BASE}/admin/content-manager/collection-types/${UID}/create`);
  await page.getByLabel(/^key/i).fill('review-empty-cov');
  await page.getByLabel(/^name/i).fill('Plan de revisión');
  await page.getByLabel(/^shortDescription/i).fill('Descripción ficticia.');
  await page.getByLabel(/^basePrice/i).fill('1000');
  await page.getByLabel(/^sortOrder/i).fill('99');
  // Coverages left untouched (an empty repeatable).
  await page.getByRole('button', { name: /^save$/i }).click();
  await page.waitForTimeout(2500);
  const afterSave = page.url();
  console.log('AFTER SAVE url is edit view:', /\/[a-z0-9]{24}/.test(afterSave));
  const alertsSave = await page.getByRole('alert').allInnerTexts().catch(() => []);
  console.log('ALERTS after save:', JSON.stringify(alertsSave));
  await page.screenshot({ path: __dirname + '/admin-after-save.png' });

  const publish = page.getByRole('button', { name: /^publish$/i });
  console.log('Publish button enabled:', await publish.isEnabled().catch(() => 'n/a'));
  if (await publish.isEnabled().catch(() => false)) {
    await publish.click();
    await page.waitForTimeout(2500);
  }
  const alertsPub = await page.getByRole('alert').allInnerTexts().catch(() => []);
  console.log('ALERTS after publish:', JSON.stringify(alertsPub));
  const covErr = await page.getByText(/coverages|at least|must have|minimum|min/i).allInnerTexts().catch(() => []);
  console.log('Coverage-related texts:', JSON.stringify(covErr.slice(0, 6)));
  await page.screenshot({ path: __dirname + '/admin-after-publish.png' });
  console.log('WRITES', JSON.stringify(writes));

  // State via the admin API, then cleanup.
  const id = (afterSave.match(/\/([a-z0-9]{24})/) || [])[1];
  if (id && auth) {
    const draft = await (await fetch(`${BASE}/content-manager/collection-types/${UID}/${id}?status=draft`, { headers: { authorization: auth } })).json();
    console.log('DRAFT coverages:', JSON.stringify(draft.data?.coverages), 'publishedAt:', draft.data?.publishedAt);
    const pub = await (await fetch(`${BASE}/content-manager/collection-types/${UID}/${id}?status=published`, { headers: { authorization: auth } })).json();
    console.log('PUBLISHED version exists:', Boolean(pub.data?.publishedAt), 'meta available statuses:', JSON.stringify(pub.meta?.availableStatus?.map((s) => s.publishedAt ? 'published' : 'draft')));
    const del = await fetch(`${BASE}/content-manager/collection-types/${UID}/${id}`, { method: 'DELETE', headers: { authorization: auth } });
